import {fighter,held,resolveRound,clamp} from './model.mjs';
import * as Art from './art.mjs';
export class TowerBattle {
 constructor(game){this.g=game;this.active=false;this.busy=false;this.session=0;this.seen=new Set();this.rewarded=new Set();this.departed=new Set()}
 start(){const g=this.g;if(!g.net.guest&&g.net.connections.size!==g.net.players.length)return g.toast('Attends que tous les alliés aient envoyé leur équipe.');if(g.net.guest){g.net.sendReady();g.toast('Équipe prête. L’hôte peut lancer le raid.');return}const parties=[{pid:g.net.myId,name:'Toi',keys:g.state.team,items:Object.fromEntries(g.state.team.map(k=>[k,held(g.state,k).key]))},...g.net.players].slice(0,4);const teams=parties.map(p=>({pid:p.pid,name:p.name,active:0,mons:p.keys.slice(0,6).map(k=>fighter(g.dex,k,g.items.find(d=>d.key===p.items?.[k])||{}))}));const floor=g.state.floor,key=String([94,6,249,150,384,487][(floor-1)%6]),boss=fighter(g.dex,key);boss.max=boss.hp=(180+floor*58)*teams.length;boss.atk=Math.round(boss.atk*(.65+floor*.025));boss.spa=Math.round(boss.spa*(.65+floor*.025));const b={id:crypto.randomUUID(),floor,teams,boss,turn:1,actions:{},over:false,win:false,log:['Le gardien bloque l’escalier. À vous de jouer.']};this.mount(b);g.net.broadcast({type:'battle-start',battle:b})}
 mount(b){this.departed.clear();this.session++;this.active=true;this.busy=false;this.data=structuredClone(b);this.visual=structuredClone(b);this.fx=null;this.g.enterMode('battle');Art.preload([b.boss.key,...b.teams.flatMap(t=>t.mons.map(m=>m.key))]);this.g.modeRoot.innerHTML=`<canvas id="battle-canvas" aria-label="Combat contre le gardien"></canvas><div class="mode-vignette"></div><div class="mode-top"><div class="mode-title"><span class="tower-symbol">♜</span><div><small>LA TOUR INFERNALE</small><strong>Étage ${String(b.floor).padStart(2,'0')} · Gardien</strong></div></div><span id="battle-turn">TOUR 1</span><div class="mode-actions"><button data-act="fullscreen" aria-label="Plein écran">⛶</button><button data-act="exit-battle">Quitter le combat</button></div></div><div class="boss-health"><small>GARDIEN DE L’ÉTAGE</small><h2>${b.boss.name}</h2><div class="boss-track"><i id="boss-fill"></i></div><span id="boss-pv"></span></div><div class="battle-commentary" id="battle-commentary">Le gardien vous défie.</div><div class="battle-command"><div class="battle-team-status" id="battle-team-status"></div><div class="battle-command-title"><span id="command-label">Quelle sera ton action ?</span><small>Une seule cible par attaque du boss</small></div><div class="battle-moves" id="battle-moves"></div><div class="reserve-bar" id="reserve-bar"></div></div><div class="battle-end" hidden><span class="eyebrow" id="battle-end-label"></span><h2 id="battle-end-title"></h2><p id="battle-end-reward"></p><button class="primary" data-act="finish-battle">Retour à la tour</button></div>`;this.canvas=this.g.modeRoot.querySelector('canvas');this.ctx=this.canvas.getContext('2d',{alpha:false});this.resize();this.observer?.disconnect();this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(this.g.modeRoot);this.updateHud();cancelAnimationFrame(this.raf);const loop=t=>{if(!this.active)return;this.draw(t/1000);this.raf=requestAnimationFrame(loop)};this.raf=requestAnimationFrame(loop)}
 resize(){if(!this.canvas)return;const b=this.g.modeRoot.getBoundingClientRect();this.scale=b.width<700?1.6:2;this.canvas.width=Math.round(b.width/this.scale);this.canvas.height=Math.round(b.height/this.scale);this.ctx.imageSmoothingEnabled=false}
 me(){return this.data.teams.find(t=>t.pid===this.g.net.myId)||this.data.teams[0]}
 act(action){if(!this.active||this.busy||this.data.over)return;const me=this.me(),mon=me.mons[me.active];if(this.data.actions[me.pid]||!me.mons.some(m=>m.hp>0))return;if(action.move!==undefined&&(!mon.moves[action.move]||mon.moves[action.move].left<=0||mon.hp<=0))return;if(action.swap!==undefined&&(!me.mons[action.swap]?.hp||me.active===action.swap))return;this.data.actions[me.pid]=action;if(this.g.net.guest){this.g.net.host.send({type:'action',battleId:this.data.id,action});this.updateHud();return}this.resolve()}
 remoteAction(pid,action,battleId){if(!this.active||this.busy||this.data.over||battleId!==this.data.id||this.data.actions[pid])return;const t=this.data.teams.find(t=>t.pid===pid);if(!t||!action)return;const p=t.mons[t.active];if(action.move!==undefined&&(!Number.isInteger(action.move)||!p.moves[action.move]?.left||!p.hp))return;if(action.swap!==undefined&&(!Number.isInteger(action.swap)||!t.mons[action.swap]?.hp||t.active===action.swap))return;if(action.move===undefined&&action.swap===undefined)return;this.data.actions[pid]=action;this.resolve()}
 resolve(){const before=structuredClone(this.data),events=resolveRound(this.data,this.g.chart);if(!events){this.g.net.broadcast({type:'battle-wait',battleId:this.data.id,actions:this.data.actions});this.updateHud();return}const serial=this.data.turn;const final=structuredClone(this.data);this.g.net.broadcast({type:'battle-turn',battle:final,before,events,serial});this.play(before,events,final,serial)}
 async receive(packet){if(packet.type==='battle-roster'&&this.active&&this.data.id===packet.battle.id){this.data=structuredClone(packet.battle);this.visual=structuredClone(packet.battle);this.updateHud();return}if(packet.type==='battle-start')this.mount(packet.battle);if(packet.type==='battle-wait'&&this.data?.id===packet.battleId){this.data.actions=packet.actions;this.updateHud()}if(packet.type==='battle-turn'&&this.active&&this.data.id===packet.battle.id)await this.play(packet.before,packet.events,packet.battle,packet.serial)}
 async play(before,events,final,serial){const token=final.id+':'+serial;if(this.seen.has(token))return;this.seen.add(token);this.busy=true;this.data=structuredClone(final);this.visual=structuredClone(before);this.updateHud();const session=this.session;for(const event of events){if(!this.active||session!==this.session)return;if(event.kind==='swap'){const t=this.visual.teams.find(t=>t.pid===event.pid);if(t)t.active=t.mons.findIndex(m=>m.key===event.key);this.fx={...event,start:performance.now()/1000};this.caption(`${this.g.poke(event.key).name} entre en scène.`);await this.sleep(220);continue}if(event.kind==='ko'){this.caption(`${this.g.poke(event.key).name} est K.O. !`);continue}this.fx={...event,start:performance.now()/1000};this.caption(`${this.g.poke(event.sourceKey).name} utilise ${event.move} !`);this.g.audio.attack(event.type);await this.sleep(this.g.state.settings.reducedMotion?150:570);if(!this.active||session!==this.session)return;const target=event.target==='boss'?this.visual.boss:this.visual.teams.find(t=>t.pid===event.target)?.mons.find(m=>m.key===event.targetKey);if(target)target.hp=event.hp;this.updateHud();await this.sleep(this.g.state.settings.reducedMotion?80:360)}if(!this.active||session!==this.session)return;this.fx=null;final.teams=final.teams.filter(t=>!this.departed.has(t.pid));this.data=structuredClone(final);this.visual=structuredClone(final);this.busy=false;this.updateHud();if(final.over)this.finishResult();else this.caption('À vous de jouer. Choisissez une attaque ou un remplaçant.')}
 sleep(ms){return new Promise(r=>setTimeout(r,ms))}
 caption(text){const el=this.g.modeRoot.querySelector('#battle-commentary');if(el)el.textContent=text}
 updateHud(){if(!this.active)return;const b=this.visual,me=this.me(),mon=me.mons[me.active],root=this.g.modeRoot;root.querySelector('#boss-fill').style.width=b.boss.hp/b.boss.max*100+'%';root.querySelector('#boss-pv').textContent=Math.max(0,b.boss.hp)+' / '+b.boss.max+' PV';root.querySelector('#battle-turn').textContent='TOUR '+this.data.turn;root.querySelector('#battle-team-status').innerHTML=this.data.teams.map(t=>{const p=t.mons[t.active];return `<div class="ally-status"><span>${t.pid===this.g.net.myId?'Toi':this.g.escape(t.name)}</span><b>${p.name}${p.key.endsWith('s')?' ✦':''}</b><i><em style="width:${p.hp/p.max*100}%"></em></i><small>${p.hp} / ${p.max} PV</small></div>`}).join('');const waiting=this.data.actions[me.pid],disabled=this.busy||this.data.over||waiting||mon.hp<=0;root.querySelector('#command-label').textContent=this.busy?'Les attaques s’enchaînent…':waiting?'En attente des alliés…':mon.hp<=0?'Ton équipe est K.O. — tes alliés poursuivent le combat.':'Que doit faire '+mon.name+' ?';root.querySelector('#battle-moves').innerHTML=mon.moves.map((m,i)=>`<button data-act="battle-move" data-slot="${i}" ${disabled||m.left<=0?'disabled':''} style="--type-color:${(Art.COLORS[m.type]||Art.COLORS.normal)[0]}"><b>${m.name}</b><small>${Art.TYPE_NAMES[m.type]||m.type} · ${m.power} puissance · ${m.left}/${m.pp} PP</small></button>`).join('');root.querySelector('#reserve-bar').innerHTML=me.mons.map((p,i)=>`<button data-act="battle-swap" data-slot="${i}" class="${me.active===i?'selected':''}" ${disabled||!p.hp||i===me.active?'disabled':''} title="${p.name} : ${p.hp}/${p.max} PV"><img src="${Art.icon(p.key)}" alt="${p.name}"><span>${p.hp}/${p.max}</span></button>`).join('')+Array.from({length:6-me.mons.length},()=>'<span class="empty-reserve">+</span>').join('')}
 positions(){const w=this.canvas.width,h=this.canvas.height,root=this.g.modeRoot,rect=root.getBoundingClientRect(),dock=root.querySelector('.battle-command').getBoundingClientRect().height/this.scale,caption=root.querySelector('.battle-commentary').getBoundingClientRect();const start=(caption.bottom-rect.top)/this.scale+12,end=h-dock-16,available=Math.max(105,end-start);const pos={boss:{x:w*.5,y:start+available*.23},bossSize:Math.min(w*.38,available*.75,170),allySize:Math.min(92,w/(this.visual.teams.length+2),available*.38)};this.visual.teams.forEach((t,i)=>pos[t.pid]={x:w*(i+1)/(this.visual.teams.length+1),y:start+available*.82});return pos}
 draw(time){const c=this.ctx,w=this.canvas.width,h=this.canvas.height,p=this.positions();c.fillStyle='#121824';c.fillRect(0,0,w,h);Art.terrain(c,200,200,w,h,time);c.fillStyle='#0b101c99';c.fillRect(0,0,w,h);for(const x of [w*.12,w*.88]){c.fillStyle='#575057';c.fillRect(x-9,50,18,h*.61);c.fillStyle='#292c39';c.fillRect(x+3,50,6,h*.61);c.fillStyle='#8e6f62';c.fillRect(x-12,50,24,7);Art.flame(c,x,h*.38,12,time+x)}c.fillStyle='#181c28';c.beginPath();c.ellipse(p.boss.x,p.boss.y+28,70,24,0,0,7);c.fill();c.strokeStyle='#886047';c.lineWidth=2;c.stroke();for(const t of this.visual.teams){const a=p[t.pid];c.fillStyle='#181c28';c.beginPath();c.ellipse(a.x,a.y+19,29,11,0,0,7);c.fill();c.strokeStyle=t.pid===this.g.net.myId?'#ceaa6f':'#59697c';c.lineWidth=1;c.stroke()}const fx=this.fx,elapsed=fx?time-fx.start:0;const drawActor=(pid,mon,size,dir)=>{const point={...p[pid]};let kind='Idle';if(fx?.kind==='attack'){if(fx.source===pid&&elapsed<.55){kind='Attack';if(!this.g.state.settings.reducedMotion){const target=p[fx.target];point.x+=(target.x-point.x)*Math.sin(Math.min(1,elapsed/.55)*Math.PI)*.055;point.y+=(target.y-point.y)*Math.sin(Math.min(1,elapsed/.55)*Math.PI)*.055}}if(fx.target===pid&&elapsed>.52&&elapsed<.95){kind='Hurt';c.globalAlpha=Math.floor(elapsed*18)%2?.55:1}}Art.drawMon(c,mon.key,point.x,point.y,size,kind,dir,time);c.globalAlpha=1};drawActor('boss',this.visual.boss,p.bossSize,0);for(const t of this.visual.teams)drawActor(t.pid,t.mons[t.active],p.allySize,4);
 if(fx?.kind==='attack'&&p[fx.source]&&p[fx.target]){const a=p[fx.source],b=p[fx.target],t=clamp((elapsed-.12)/.45,0,1);if(elapsed>.12&&elapsed<.62){const x=a.x+(b.x-a.x)*t,y=a.y+(b.y-a.y)*t,colors=Art.COLORS[fx.type]||Art.COLORS.normal;for(let i=4;i>=0;i--){const q=Math.max(0,t-i*.045);c.globalAlpha=1-i*.17;c.fillStyle=colors[i%3];const size=12-i;c.fillRect(a.x+(b.x-a.x)*q-size/2,a.y+(b.y-a.y)*q-size/2,size,size)}c.globalAlpha=1;if(fx.type==='electric'){c.strokeStyle=colors[1];c.lineWidth=2;c.beginPath();c.moveTo(a.x,a.y);for(let i=1;i<8;i++)c.lineTo(a.x+(x-a.x)*i/8+(i%2?6:-6),a.y+(y-a.y)*i/8);c.lineTo(x,y);c.stroke()}}if(elapsed>.5&&elapsed<1)Art.hitEffect(c,{x:b.x,y:b.y,life:1-elapsed,max:.5,type:fx.type,n:fx.amount,text:fx.amount?'−'+fx.amount:fx.text},0,0)}
 const shade=c.createLinearGradient(0,0,0,h);shade.addColorStop(0,'#0b101a66');shade.addColorStop(.5,'#0b101a00');shade.addColorStop(1,'#0b101a99');c.fillStyle=shade;c.fillRect(0,0,w,h)}
 finishResult(){const b=this.data,g=this.g;if(b.win&&!this.rewarded.has(b.id)){this.rewarded.add(b.id);g.state.floor=Math.max(g.state.floor,b.floor+1);g.state.tickets+=2;g.state.coins+=50;g.save();g.audio.chime('legendary')}const end=g.modeRoot.querySelector('.battle-end');end.hidden=false;g.modeRoot.querySelector('#battle-end-label').textContent=b.win?'LE GARDIEN EST VAINCU':'LA TOUR GARDE SES SECRETS';g.modeRoot.querySelector('#battle-end-title').textContent=b.win?'Victoire !':'Ton équipe est K.O.';g.modeRoot.querySelector('#battle-end-reward').textContent=b.win?'+2 tickets universels · +50 fragments · Étage suivant débloqué':'Tes Pokémon seront soignés au camp. Change de stratégie et réessaie.'}
 removePlayer(pid){if(!this.active||this.g.net.guest)return;this.departed.add(pid);this.data.teams=this.data.teams.filter(t=>t.pid!==pid);this.visual.teams=this.visual.teams.filter(t=>t.pid!==pid);delete this.data.actions[pid];if(!this.busy){this.g.net.broadcast({type:'battle-roster',battle:this.data});this.resolve()}}
 stop(){this.active=false;this.busy=false;this.session++;cancelAnimationFrame(this.raf);this.observer?.disconnect();this.fx=null;this.g.leaveMode();this.g.route('home')}
}
